// ---- cash register + thunder samples ----
const CASHTH_SRC={cash:'data:audio/mpeg;base64,',thunder:'data:audio/mpeg;base64,'};
const CASHTH={cash:null,thunder:null,ld:false};
function cashthLoad(c){if(CASHTH.ld||!c)return;CASHTH.ld=true;['cash','thunder'].forEach(k=>{try{const bin=atob(CASHTH_SRC[k].split(',')[1]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const p=c.decodeAudioData(u.buffer,b=>{CASHTH[k]=b},()=>{});if(p&&p.catch)p.catch(()=>{})}catch(e){}})}
function cashthPlay(k,vol,rate){const c=sndCtx();if(!c)return false;cashthLoad(c);const b=CASHTH[k];if(!b)return false;const s=c.createBufferSource();s.buffer=b;s.playbackRate.value=rate||1;const g=c.createGain();g.gain.value=vol;s.connect(g);g.connect(SND.master);s.start();return true}
SFX.thunder=function(){try{if(sndOk('thunder',1500))cashthPlay('thunder',.7,.97+Math.random()*.06)}catch(e){}};
(function(){const _cash=SFX.cash;SFX.cash=function(){try{if(cashthPlay('cash',.7,1))return}catch(e){}return _cash.apply(this,arguments)};
 const _om=openModal;openModal=function(h){const r=_om.apply(this,arguments);
  try{if(typeof h==='string'&&h.indexOf('data-act="evopt"')>=0){const mt=h.match(/<h2>(.*?)<\/h2>/);if(mt&&/burza w dniu|grzmot|piorun|nawa[łl]nic|thunderstorm|storm on/i.test(mt[1]))setTimeout(()=>sPlay('thunder'),300)}}catch(e){}
  return r};
 try{if(typeof window!=='undefined')window.addEventListener('pointerdown',()=>{try{const c=sndCtx();if(c)cashthLoad(c)}catch(e){}},{once:true,capture:true})}catch(e){}})();
